import type { CodeOwnerItem, EvidenceSource } from '@argon/agent';

/**
 * Provenance helpers for the briefing UI. Every link comes from `response.sources`, which the
 * server builds from graph properties only (commit / ADR / PR / issue URLs stored on nodes);
 * nothing here is generated by the model.
 */

const clean = (id: string): string => (id.startsWith('#') ? id.slice(1) : id);

const isHttp = (url: unknown): url is string => {
  if (typeof url !== 'string') return false;
  try {
    const u = new URL(url);
    return u.protocol === 'https:' || u.protocol === 'http:';
  } catch {
    return false;
  }
};

/** Keeps only sources that carry a real http(s) link (defence in depth: href never gets `javascript:`). */
export function linkableSources(sources: EvidenceSource[] | null | undefined): EvidenceSource[] {
  return (sources ?? []).filter((s) => s && isHttp(s.url));
}

export interface DecisionProvenance {
  /** The decision's own origin: the commit, or the ADR / RFC document, it was found in. */
  origin?: EvidenceSource;
  /** What it came from: the pull request and the issue that PR closed. */
  links: EvidenceSource[];
}

export function decisionProvenance(
  sources: EvidenceSource[] | null | undefined,
  decisionId: string
): DecisionProvenance {
  const id = clean(decisionId);
  const mine = linkableSources(sources).filter((s) => s.relatedTo === id);
  const origin = mine.find((s) => s.nodeId === id && (s.kind === 'commit' || s.kind === 'document' || s.kind === 'decision'));
  const links = mine.filter((s) => s !== origin && (s.kind === 'pull_request' || s.kind === 'issue'));
  // pull requests first, then issues
  links.sort((a, b) => (a.kind === b.kind ? 0 : a.kind === 'pull_request' ? -1 : 1));
  return { origin, links };
}

/** Links for the nodes a claim cites: a claim that cites `pr_gh_5` gets that PR's URL. */
export function citationLinks(
  sources: EvidenceSource[] | null | undefined,
  citedNodeIds: string[] | undefined
): EvidenceSource[] {
  const linkable = linkableSources(sources);
  const out: EvidenceSource[] = [];
  const seen = new Set<string>();
  for (const raw of citedNodeIds ?? []) {
    const id = clean(raw);
    const hit = linkable.find((s) => s.nodeId === id && (s.kind === 'pull_request' || s.kind === 'issue'));
    if (hit && !seen.has(hit.url!)) {
      seen.add(hit.url!);
      out.push(hit);
    }
  }
  return out;
}

/** Short label for a link chip: "PR #42" / "Issue #1042" / "commit". */
export function sourceChipLabel(s: EvidenceSource): string {
  const m = /^(PR|Issue) (#\d+)/.exec(s.label);
  if (m) return `${m[1]} ${m[2]}`;
  if (s.kind === 'pull_request') return 'PR';
  if (s.kind === 'issue') return 'Issue';
  if (s.kind === 'commit') return 'Commit';
  return 'Source';
}

/** The CODEOWNERS owners of record for a component. */
export function ownersOfRecord(
  codeOwners: CodeOwnerItem[] | null | undefined,
  component?: string
): CodeOwnerItem[] {
  return (codeOwners ?? []).filter((o) => !component || o.component === component);
}
